import json, time, urllib.request, urllib.error, sys
B="http://localhost:8080"
tok=None
def raw(path, method="GET", auth=True):
    global tok
    for attempt in range(200):
        h={}
        if auth:
            if not tok:
                tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b"")))["token"]
            h["Authorization"]="Bearer "+tok
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+path,headers=h,method=method)))
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==404: return {"__404":True}
            if e.code==401: tok=None; continue
            if e.code==429:
                w=e.headers.get("Retry-After")
                try: w=float(w)
                except: 
                    try: w=float(json.loads(body).get("retry_after",2))
                    except: w=2
                print("429 wait",w,body[:100],file=sys.stderr); time.sleep(w+0.2); continue
            print("err",e.code,path,body[:150],file=sys.stderr); time.sleep(1)
        except Exception as e:
            print("exc",path,e,file=sys.stderr); time.sleep(1)
    raise SystemExit("gave up "+path)
